}

class RetryInterceptor(
    private val maxAttempts: Int = 3,
    private val baseDelayMillis: Long = 500,
) : Interceptor {
    private val idempotent = setOf("GET", "HEAD", "PUT", "DELETE")

    override fun intercept(chain: Interceptor.Chain): Response {
        val request = chain.request()
        var attempt = 0
        while (true) {
            val response = chain.proceed(request)
            val retryable = response.code() in setOf(429, 503) &&
                request.method in idempotent
            if (attempt >= maxAttempts - 1 || !retryable) return response

            response.close()
            attempt++
            val delay = baseDelayMillis * (1L shl (attempt - 1)) +
                Random.nextLong(0, baseDelayMillis)   // jitter
            Thread.sleep(delay)
        }
    }
}

