import androidx.compose.material3.adaptive.currentWindowAdaptiveInfo
import androidx.compose.material3.windowsizeclass.WindowWidthSizeClass

@Composable
fun BrowseScreen(viewModel: BrowseViewModel) {
    // Recomputed after every config change, inside the composition
    val windowSizeClass = currentWindowAdaptiveInfo().windowSizeClass
    val isTwoPane = windowSizeClass.windowWidthSizeClass >= WindowWidthSizeClass.Expanded

    // ViewModel state is configuration-independent: survives rotation untouched
    val state by viewModel.state.collectAsStateWithLifecycle()

    if (isTwoPane) {
        MasterDetailPane(state, onSelect = viewModel::select)
    } else {
        SinglePane(state, onSelect = viewModel::select)
    }
}

