fun BrowseScreen(viewModel: BrowseViewModel = hiltViewModel()) {
    val state by viewModel.state.collectAsStateWithLifecycle()
    LazyColumn {
        items(state.items, key = Item::id) { item ->
            ItemCard(
                item = item,
                isSelected = item.id == state.selectedId,
                onSelect = viewModel::select,
            )
        }
    }
}

class FeedRepository(
    private val dao: FeedDao,
    private val api: FeedApi,
    private val scope: CoroutineScope,
) {
    // Cold: fresh query per collector — the read default
    fun observeLocal(): Flow<List<FeedItem>> = dao.observeAll()

    // Hot: one in-flight fetch shared by every collector
    fun observeShared(): Flow<List<FeedItem>> = flow {
        emit(api.fetch())   // runs once for all collectors
    }.shareIn(scope, SharingStarted.WhileSubscribed(5000), replay = 1)

    // Hot + value: identical current state for everyone
    val connection: StateFlow<ConnectionState> = api.observeSocket()
        .map(ConnectionState::of)
        .stateIn(scope, SharingStarted.WhileSubscribed(5000), ConnectionState.Disconnected)
}

// combine: two independent inputs, one derived value — both stay live
val visibleFeed: Flow<List<FeedItem>> = combine(
    repository.observeFeed(),
    filters.chips(),
) { feed, chips ->
    feed.filter { item -> chips.all { it.accepts(item) } }
}

