@OptIn(ExperimentalCoroutinesApi::class)
class FeedViewModelTest {

    @get:Rule
    val mainDispatcherRule = MainDispatcherRule()

    @Test
    fun `load emits items from the fake repository`() = runTest {
        val repo = FakeFeedRepository(items = listOf(sampleItem()))
        val viewModel = FeedViewModel(repo)

        advanceUntilIdle()

        assertEquals(listOf(sampleItem()), viewModel.state.value.items)
        assertFalse(viewModel.state.value.isRefreshing)
    }

    @Test
    fun `failed refresh keeps cached content and surfaces an error`() = runTest {
        val repo = FakeFeedRepository(items = listOf(sampleItem()), failRefresh = true)
        val viewModel = FeedViewModel(repo)

        advanceUntilIdle()
        viewModel.refresh()
        advanceUntilIdle()

        assertEquals(listOf(sampleItem()), viewModel.state.value.items)
        assertNotNull(viewModel.state.value.error)
    }
}

class MainDispatcherRule(
    private val dispatcher: TestDispatcher = StandardTestDispatcher(),
) : TestWatcher() {
    override fun starting(description: Description) {
        Dispatchers.setMain(dispatcher)
    }

    override fun finished(description: Description) {
        Dispatchers.resetMain()
    }
}

class FakeFeedRepository(
    private val items: List<FeedItem>,
    private val failRefresh: Boolean = false,
) : FeedRepository {
    private val _items = MutableStateFlow(items)

    override fun observe(): Flow<List<FeedItem>> = _items

    override suspend fun refresh() {
        if (failRefresh) throw IOException("offline")
        _items.value = items   // a successful refresh keeps the seeded data
    }
}

@Entity
data class ProfileEntity(
    @PrimaryKey val userId: String,
    val displayName: String,
    val avatarVersion: Int,
)

@Dao
interface ProfileDao {
    @Query("SELECT * FROM profile WHERE userId = :id")
    fun observe(userId: String): Flow<ProfileEntity?>

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun upsert(profile: ProfileEntity)
}

class ProfileRepository(
    private val dao: ProfileDao,
    private val prefs: DataStore<Preferences>,
    private val imageCache: ImageCache,
) {
    // Reads always observe the authority
    fun observe(userId: String): Flow<Profile> =
        dao.observe(userId).map { it?.toDomain() }

    suspend fun save(profile: Profile) = withContext(io) {
        dao.upsert(profile.toEntity())
        imageCache.evict(profile.userId)   // caches follow the authority
    }

    val darkMode: Flow<Boolean> =
        prefs.data.map { it[KEY_DARK_MODE] ?: false }   // DataStore is its own authority
}

// Solo/duo: one :app module, but the seams that make modularization cheap later
// — constructor injection and interfaces at the data boundary.
interface FeedRepository {
    fun observe(): Flow<List<FeedItem>>
}

class FeedViewModel(private val repo: FeedRepository) : ViewModel() {
    val state: StateFlow<FeedUiState> = repo.observe()
        .map { FeedUiState(items = it) }
        .stateIn(viewModelScope, SharingStarted.Eagerly, FeedUiState())
}

